"""Convert legacy Qwen3-ASR Hub layouts to Transformers-native ``*-hf`` layout.

Weights stay; processor/tokenizer/config sidecars are taken from an official
``*-hf`` template (same approach as jaykwok's published conversion).
"""

from __future__ import annotations

import logging
import shutil
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_convert")

# Sidecars that differ between qwen-asr layout and Transformers-native -hf.
_HF_SIDECAR_NAMES = (
    "config.json",
    "generation_config.json",
    "processor_config.json",
    "tokenizer.json",
    "tokenizer_config.json",
    "chat_template.jinja",
    "preprocessor_config.json",
)

_LEGACY_ONLY_NAMES = (
    "chat_template.json",
    "merges.txt",
    "vocab.json",
    "added_tokens.json",
    "special_tokens_map.json",
)

_DEFAULT_ASR_TEMPLATE = "Qwen/Qwen3-ASR-1.7B-hf"
_DEFAULT_ALIGN_TEMPLATE = "Qwen/Qwen3-ForcedAligner-0.6B-hf"

# Model ids that ship non-hf hubs and need post-download conversion.
CONVERT_AFTER_DOWNLOAD_IDS = frozenset()

# Repair hybrid Hub ports that still ship legacy chat_template.json.
REPAIR_AFTER_DOWNLOAD_IDS = frozenset(
    {
        "qwen3-asr-0.6b",
        "qwen3-asr-1.7b",
        "qwen3-asr-1.7b-ja-anime-galgame",
        "qwen3-forced-aligner-0.6b",
    }
)


def looks_like_hf_layout(root: Path | str) -> bool:
    """True when layout supports Transformers-native ``continue_final_message``.

    Official ``*-hf`` ports ship ``chat_template.jinja``. Hybrid checkpoints that
    keep legacy ``chat_template.json`` (only ``add_generation_prompt``) break
    ``apply_transcription_request`` language prefills — treat those as incomplete.
    """
    path = Path(root)
    if not path.is_dir():
        return False
    if not (path / "config.json").is_file():
        return False
    has_tok = (path / "tokenizer.json").is_file()
    has_jinja = (path / "chat_template.jinja").is_file()
    legacy_tmpl = (path / "chat_template.json").is_file() or (path / "merges.txt").is_file()
    if has_jinja and has_tok:
        return True
    if has_jinja and (path / "processor_config.json").is_file():
        return True
    # tokenizer.json alone is ok only when no legacy chat/merges sidecars remain.
    if has_tok and not legacy_tmpl:
        return True
    return False


def looks_like_legacy_qwen_layout(root: Path | str) -> bool:
    path = Path(root)
    if not path.is_dir() or not (path / "config.json").is_file():
        return False
    if looks_like_hf_layout(path):
        return False
    return (path / "merges.txt").is_file() or (path / "chat_template.json").is_file()


def needs_hf_sidecar_repair(root: Path | str) -> bool:
    """Weights present but chat/tokenizer sidecars still legacy / hybrid."""
    path = Path(root)
    return _weight_present(path) and not looks_like_hf_layout(path)


def _weight_present(root: Path) -> bool:
    if (root / "model.safetensors").is_file():
        return True
    if (root / "model.safetensors.index.json").is_file():
        return True
    if (root / "pytorch_model.bin").is_file():
        return True
    # Sharded safetensors without index name pattern
    try:
        for p in root.glob("model-*.safetensors"):
            if p.is_file() and p.stat().st_size > 1024:
                return True
    except OSError:
        pass
    return False


def template_hub_for_model_id(model_id: str) -> str:
    mid = str(model_id or "").strip().lower()
    if "align" in mid:
        return _DEFAULT_ALIGN_TEMPLATE
    if "0.6" in mid:
        return "Qwen/Qwen3-ASR-0.6B-hf"
    return _DEFAULT_ASR_TEMPLATE


def _fetch_template_sidecars(template_hub: str, cache_dir: Path) -> Path:
    """Download only non-weight files from ``template_hub`` into ``cache_dir``."""
    from huggingface_hub import snapshot_download

    cache_dir.mkdir(parents=True, exist_ok=True)
    ignore = [
        "*.safetensors",
        "*.bin",
        "*.pt",
        "*.pth",
        "*.onnx",
        "*.msgpack",
        "*.h5",
        "optimizer.pt",
        "scheduler.pt",
        "rng_state.pth",
        "trainer_state.json",
        "training_args.bin",
    ]
    snapshot_download(
        repo_id=template_hub,
        local_dir=str(cache_dir),
        ignore_patterns=ignore,
        max_workers=4,
    )
    return cache_dir


def convert_dir_to_hf_layout(
    dest: Path | str,
    *,
    template_hub: str | None = None,
    model_id: str | None = None,
    force: bool = False,
) -> dict[str, Any]:
    """Rewrite ``dest`` sidecars to match an official ``*-hf`` template.

    Keeps weight files in place. Returns ``{ok, skipped?, converted?, detail}``.
    """
    root = Path(dest)
    if not root.is_dir():
        return {"ok": False, "detail": f"missing dir: {root}"}
    if not _weight_present(root):
        return {"ok": False, "detail": f"no weights under {root}"}
    if looks_like_hf_layout(root) and not force:
        return {"ok": True, "skipped": True, "detail": "already -hf layout"}

    hub = str(template_hub or template_hub_for_model_id(model_id or "")).strip()
    if not hub:
        hub = _DEFAULT_ASR_TEMPLATE

    cache = root / ".cache" / "hf-template" / hub.replace("/", "__")
    try:
        _fetch_template_sidecars(hub, cache)
    except Exception as err:
        return {"ok": False, "detail": f"template fetch failed ({hub}): {err}"}

    copied = 0
    for name in _HF_SIDECAR_NAMES:
        src = cache / name
        if not src.is_file():
            continue
        shutil.copy2(src, root / name)
        copied += 1

    # Drop legacy-only sidecars that confuse AutoProcessor.
    removed = 0
    for name in _LEGACY_ONLY_NAMES:
        legacy = root / name
        if legacy.is_file():
            try:
                legacy.unlink()
                removed += 1
            except OSError:
                pass

    if not looks_like_hf_layout(root):
        return {
            "ok": False,
            "detail": (
                f"conversion incomplete under {root} "
                f"(copied={copied}, removed={removed}, template={hub})"
            ),
        }
    _log.info(
        "Qwen3-ASR converted to -hf layout: %s (template=%s, sidecars=%d, removed=%d)",
        root,
        hub,
        copied,
        removed,
    )
    return {
        "ok": True,
        "converted": True,
        "detail": f"converted via {hub}",
        "copied": copied,
        "removed": removed,
    }


def maybe_convert_after_download(model_id: str, dest: Path | str) -> dict[str, Any]:
    """One-liner hook for download.py — convert / repair sidecars after Hub pull."""
    mid = str(model_id or "").strip()
    root = Path(dest)
    if mid in CONVERT_AFTER_DOWNLOAD_IDS:
        return convert_dir_to_hf_layout(
            root,
            template_hub=template_hub_for_model_id(mid),
            model_id=mid,
            force=False,
        )
    if mid in REPAIR_AFTER_DOWNLOAD_IDS and needs_hf_sidecar_repair(root):
        return convert_dir_to_hf_layout(
            root,
            template_hub=template_hub_for_model_id(mid),
            model_id=mid,
            force=True,
        )
    return {"ok": True, "skipped": True, "detail": "no convert needed"}
